import React from 'react';

import Card from 'react-bootstrap/Card';
import { Container, Row, Col } from 'react-bootstrap';
import Badge from 'react-bootstrap/Badge';
import { cognizant, google, photoshop, zoho, ionic, crescentLogo } from '../assets/index';
import experienceData from '../assets/experienceData.json';
import { SeoComponent } from './SeoComponent';
import { defaultImage, seoPages } from '../seo';

const imageMap = {
    cognizant,
    google,
    ionic,
    photoshop,
    zoho,
    crescentLogo
};

function ExperienceCard({ item }) {
    const image = imageMap[item.imageKey];
    const hasWebsite = Boolean(item.websiteUrl);
    const titleContent = hasWebsite ? (
        <a href={item.websiteUrl} target="_blank" rel="noreferrer noopener" style={{color:"darkkhaki"}}>
            {item.title}
        </a>
    ) : (
        item.title
    );

    return (
        <Card style={{ paddingLeft: "0px" }} as="article">
            <Row>
                <Col md={3} className="cardImage">
                    <Card.Header style={{ background: "transparent" }}>
                        {hasWebsite ? (
                            <a href={item.websiteUrl} target="_blank" rel="noreferrer noopener">
                                <Card.Img variant="top" src={image} alt={item.title} />
                            </a>
                        ) : (
                            <Card.Img variant="top" src={image} alt={item.title} />
                        )}
                    </Card.Header>
                </Col>
                <Col md={9} className="cardbody">
                    <Card.Body>
                        <Row>
                            <Col md={12} style={{ textAlign: "left" }}>
                                <h5 style={{color:"yellow"}}><b>{titleContent}</b></h5>
                                <hr />

                                <Row>
                                    {item.meta.map((meta) => (
                                        <Col sm="auto" key={`${item.title}-${meta.label}`}>
                                            {meta.label}: <b>{meta.value}</b>
                                        </Col>
                                    ))}
                                </Row>

                                {item.summary ? (
                                    <>
                                        <hr />
                                        <Row>
                                            <Col sm="auto">
                                                <b>{item.summary}</b>
                                            </Col>
                                        </Row>
                                    </>
                                ) : null}

                                {item.description ? (
                                    <>
                                        <hr />
                                        <h6 style={{ marginBottom: "10px" }}>Description</h6>
                                        <ul style={{ paddingLeft: "20px", marginBottom: "0" }}>
                                            {item.description.map((point) => (
                                                <li key={`${item.title}-${point}`}>{point}</li>
                                            ))}
                                        </ul>
                                    </>
                                ) : null}

                                <hr />
                                <h6>
                                    Technical Tools{":   "}
                                    {item.tools.map((tool) => (
                                        <Badge key={`${item.title}-${tool}`} pill style={{marginInline:"5px"}} text="dark" bg="info">
                                            {tool}
                                        </Badge>
                                    ))}
                                </h6>
                            </Col>
                        </Row>
                    </Card.Body>
                </Col>
            </Row>
        </Card>
    );
}

export function ExperienceComponent() {
    return (
        <div>
            <SeoComponent {...seoPages.experience} image={defaultImage} />
            <Container style={{ paddingBottom: "50px" }}>
                {experienceData.sections.map((section) => (
                    <React.Fragment key={section.title}>
                        <h4 style={{ textAlign: "left", paddingTop: "20px" }} className="resumeHeader">
                            {section.title}
                        </h4>
                        <Container style={{ fontSize: "larger", color: "white" }}>
                            {section.items.map((item, index) => (
                                <React.Fragment key={item.title}>
                                    <Row>
                                        <ExperienceCard item={item} />
                                    </Row>
                                    {index < section.items.length - 1 ? <div style={{ padding: "20px" }} /> : null}
                                </React.Fragment>
                            ))}
                        </Container>
                    </React.Fragment>
                ))}
            </Container>
        </div>
    );
}