import React from 'react';
import { Container, Button } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { SeoComponent } from './SeoComponent';
import { defaultImage, seoPages } from '../seo';

export class PageNotFoundComponent extends React.Component {

    componentDidMount() {
        document.title = 'Page Not Found | Mohamad Yasar J';

        const ensureMetaTag = (name, content) => {
            let meta = document.querySelector(`meta[name="${name}"]`);
            if (!meta) {
                meta = document.createElement('meta');
                meta.setAttribute('name', name);
                document.head.appendChild(meta);
            }
            meta.setAttribute('content', content);
        };

        ensureMetaTag('robots', 'noindex, nofollow');
        ensureMetaTag('description', 'Page not found. Explore the portfolio of Mohamad Yasar J to view experience, education, projects, and contact details.');
    }

    componentWillUnmount() {
        document.title = 'Mohamad Yasar J';
    }

    render() {
        return (
            <div>
                <SeoComponent {...seoPages.notFound} image={defaultImage} />
                <Container style={{ paddingTop: '80px', paddingBottom: '80px' }}>
                    <h2>Sorry, page not found.</h2>
                    <p>
                        The page you requested does not exist. Explore the portfolio to view experience, education, and contact details.
                    </p>
                    <Button as={Link} to="/" variant="info">
                        Go to Home
                    </Button>
                </Container>
            </div>
        );
    }
}