import React from 'react';
import {
  BrowserRouter as Router,
  Routes, Route
} from "react-router-dom";
import './App.css';
import { NavigationBarComponent } from './Components/NavigationBarComponent';
import { AboutComponent } from './Components/AboutComponent';
import { EducationComponent } from './Components/EducationComponent';
import { ExperienceComponent } from './Components/ExperienceComponent';
import { ContactComponent } from './Components/ContactComponent';
import {PageNotFoundComponent} from './Components/404Component';
import 'bootstrap/dist/css/bootstrap.min.css';

import Particles, {ParticlesProvider} from '@tsparticles/react';
import { loadSlim } from '@tsparticles/slim';
import options from './particlesjsv4-config.json';
import './App.css';

const particlesInit = async (engine) => {
  await loadSlim(engine);
};

class App extends React.Component {
  render() {
    const particlesLoaded = (container) => {
      console.log(" particles loaded");
    };

    return (
      <div >
        <ParticlesProvider init={particlesInit}>
          <Particles id="tsparticles" particlesLoaded={particlesLoaded} options={options} />
        </ParticlesProvider>    

        <div className="App" style={{color:"white"}}>
        
        <Router>
            <NavigationBarComponent/>
            <Routes>
              <Route path="/education" element={<EducationComponent/>} />
              <Route path="/experience" element={<ExperienceComponent/>} />
              <Route path="/about" element={<AboutComponent/>} />
              <Route path="/contact" element={<ContactComponent/>} />
              <Route exact path="/" />
              <Route exact path="*" element={<PageNotFoundComponent/>} />
            </Routes>
        </Router>
        </div>
      </div>
    );
  }
}

export default App;
