import React from 'react';

function setMetaTag(attribute, key, value) {
  const selector = `meta[${attribute}="${key}"]`;
  let tag = document.querySelector(selector);

  if (!tag) {
    tag = document.createElement('meta');
    tag.setAttribute(attribute, key);
    document.head.appendChild(tag);
  }

  tag.setAttribute('content', value);
}

function setLinkTag(rel, href) {
  const selector = `link[rel="${rel}"]`;
  let tag = document.querySelector(selector);

  if (!tag) {
    tag = document.createElement('link');
    tag.setAttribute('rel', rel);
    document.head.appendChild(tag);
  }

  tag.setAttribute('href', href);
}

export class SeoComponent extends React.Component {
  componentDidMount() {
    this.applySeo(this.props);
  }

  componentDidUpdate() {
    this.applySeo(this.props);
  }

  applySeo(props) {
    const {
      title,
      description,
      canonical,
      image,
      noindex = false,
      keywords,
      siteName = 'Mohamad Yasar J - Portfolio',
      locale = 'en_US',
      twitterSite
    } = props;

    if (title) {
      document.title = title;
      setMetaTag('property', 'og:title', title);
      setMetaTag('name', 'twitter:title', title);
    }

    if (description) {
      setMetaTag('name', 'description', description);
      setMetaTag('property', 'og:description', description);
      setMetaTag('name', 'twitter:description', description);
    }

    setMetaTag('name', 'robots', noindex ? 'noindex, nofollow' : 'index, follow');
    setMetaTag('name', 'googlebot', noindex ? 'noindex, nofollow' : 'index, follow');
    setMetaTag('property', 'og:site_name', siteName);
    setMetaTag('property', 'og:locale', locale);
    setMetaTag('property', 'og:type', 'website');
    setMetaTag('name', 'twitter:card', 'summary_large_image');

    if (canonical) {
      setLinkTag('canonical', canonical);
      setMetaTag('property', 'og:url', canonical);
    }

    if (twitterSite) {
      setMetaTag('name', 'twitter:site', twitterSite);
    }

    if (image) {
      setMetaTag('property', 'og:image', image);
      setMetaTag('property', 'og:image:secure_url', image);
      setMetaTag('property', 'og:image:alt', title || siteName);
      setMetaTag('name', 'twitter:image', image);
      setMetaTag('name', 'twitter:image:alt', title || siteName);
    }

    if (keywords) {
      setMetaTag('name', 'keywords', keywords);
    }
  }

  render() {
    return null;
  }
}